# RGB updates generated by --run-geometry-fitting.
# Evidence: docs/make_kong/geometry_fit.json
"""Per-episode Kong controller with explicit recoverable boundaries.

The caller must display fresh images and decide recovery in a subsequent cell."""
import numpy as np
_VIEW_ERRORS = ('Rack not visible', 'Insufficient rack span', 'No visible green stack panels', 'No complete white panel bounded by green in observed left stack')
_MOTION_ERRORS = ('Triplet push waypoint failed', 'Retained stack motion failed', 'Retained stack exact pose unavailable', 'Canonical flat exact pose unavailable', 'Canonical flat checkpoint motion incomplete', 'Top placement move incomplete', 'Exact top placement path unavailable')

class KongEpisode:
    """One context per episode. Failure never implies a phase completed."""
    phases = ('pair_geometry', 'push', 'pickup', 'canonical', 'upright', 'receive', 'place', 'home_left', 'home_right')

    def __init__(self, policy):
        self.policy = policy
        self.index = 0
        self.indices = None
        self.pair_indices = None
        self.rack_count = None
        self.context = {}
        self.history = []
        self.blocked = None
        self.view_retries = 0

    def select(self, indices, pair_indices, rack_count=None):
        """Select the matching triplet and the adjacent placement pair from the current RGB image."""
        if self.indices is not None or self.index != 0:
            raise RuntimeError('Selection already fixed for this episode')
        indices, pair, count = self.policy.validate_selection(indices, pair_indices, rack_count)
        self.indices = list(indices)
        self.pair_indices = pair
        self.rack_count = count

    def _state(self, robo):
        action_count = robo.action_count()
        return {'action_count': action_count, 'episode_over': bool(robo.state().truncated), 'stage': self.phases[self.index] if self.index < len(self.phases) else 'complete'}

    def advance(self, robo):
        state = self._state(robo)
        if state['episode_over']:
            return dict(state, status='episode_stop')
        if self.blocked is not None:
            return dict(state, status='blocked', failure=self.blocked, instruction='Do not replay a partially executed physical phase. Inspect state/images and replan in a new cell.')
        if self.indices is None:
            raise RuntimeError('Live image semantic selection required before movement')
        if self.index == len(self.phases):
            return dict(state, status='completed_sequence', task_success='unknown')
        phase = self.phases[self.index]
        p = self.policy
        before = state['action_count']
        try:
            if phase == 'pair_geometry':
                geometry = p.standing_pair_geometry(robo.image('cam_head'), robo.camera_meta('cam_head'), indices=tuple(self.indices) + self.pair_indices, rack_count=self.rack_count)
                pair = sorted([np.asarray(x) for x in geometry['centers'][3:]], key=lambda x: x[0])
                goal = 2 * pair[1] - pair[0]
                goal[1:] = np.mean(pair, axis=0)[1:]
                self.context.update(geometry=geometry, goal=goal.tolist())
            elif phase == 'push':
                p.push_before_grasp(robo, [{'pos': x} for x in self.context['geometry']['centers'][:3]])
            elif phase == 'pickup':
                self.context['held'] = p.flat_pickup(robo, prepared=True)
            elif phase == 'canonical':
                p.canonical_flat_checkpoint(robo, self.context['held'])
            elif phase == 'upright':
                self.context['upright'] = p.donor_upright(robo, self.context['held'])
            elif phase == 'receive':
                self.context['received'] = p.top_receive(robo, self.context['upright'])
            elif phase == 'place':
                p.place_top_received(robo, self.context['goal'])
            else:
                reply = robo.home('left' if phase == 'home_left' else 'right')
                if not reply.reached and (not robo.state().truncated):
                    raise RuntimeError('Final home incomplete ' + phase)
        except Exception as exc:
            message = str(exc)
            kind = 'view' if message in _VIEW_ERRORS else 'motion' if any((message.startswith(x) for x in _MOTION_ERRORS)) else None
            if not isinstance(exc, RuntimeError):
                kind = None
            if kind is None:
                self.blocked = {'stage': phase, 'kind': 'unknown', 'message': message, 'actions_used': robo.action_count() - before, 'retry_safe': False}
                raise
            after = self._state(robo)
            self.blocked = {'stage': phase, 'kind': kind, 'message': message, 'actions_used': after['action_count'] - before, 'retry_safe': kind == 'view' and after['action_count'] == before}
            self.history.append(dict(self.blocked, status='recoverable_feedback'))
            return dict(after, status='recoverable_feedback', failure=self.blocked, instruction='Observe new RGB/proprioception; clear only a verified empty occluding arm by checked waypoints if needed. No automatic repeat of physical actions.')
        after = self._state(robo)
        if after['episode_over']:
            result = dict(after, status='episode_stop', interrupted_stage=phase, actions_used=after['action_count'] - before)
            self.history.append(result)
            return result
        self.index += 1
        result = dict(self._state(robo), completed_stage=phase, status='advanced', actions_used=robo.action_count() - before)
        self.history.append(result)
        return result

    def retry_view(self, robo):
        if not self.blocked or not self.blocked['retry_safe']:
            raise RuntimeError('Only zero-action perception abstention may be retried here')
        if self.view_retries >= 2:
            raise RuntimeError('Two view recovery retries exhausted; replan through public agent tools')
        state = self._state(robo)
        if state['episode_over']:
            return dict(state, status='episode_stop')
        self.view_retries += 1
        self.blocked = None
        return self.advance(robo)

    def clear_empty_view(self, robo, arm, waypoints, *, visually_empty):
        """Checked, caller-planned clearance; leaves retry to a subsequent cell.

        Only an untouched pickup detector failure establishes no new grasp action.
        Proprioception and caller RGB assessment must agree that the arm is empty.
        Exact kinematics is not a complete scene collision oracle.
        """
        if not self.blocked or not self.blocked['retry_safe'] or self.blocked['stage'] != 'pickup' or ('held' in self.context):
            raise RuntimeError('Empty view clearance only before untouched pickup')
        if visually_empty is not True or arm not in ('left', 'right'):
            raise ValueError('Explicit current RGB empty-arm verification required')
        if not isinstance(waypoints, list) or not 1 <= len(waypoints) <= 2:
            raise ValueError('One or two bounded clearance waypoints required')
        count = getattr(self, 'clearance_attempts', 0)
        if count >= 2:
            raise RuntimeError('Two empty view clearance attempts exhausted')
        state = self._state(robo)
        if state['episode_over']:
            return dict(state, status='episode_stop')
        a = robo.state().arm(arm)
        if not (a.gripper < 0.1 or a.gripper > 0.95):
            raise RuntimeError('Intermediate gripper width; possible held object, no empty clearance')
        self.clearance_attempts = count + 1
        origin = np.asarray(a.tcp_pos, float)
        prior = origin.copy()
        points = []
        for raw in waypoints:
            xyz = np.asarray(raw, float)
            if xyz.shape != (3,) or not np.isfinite(xyz).all() or np.linalg.norm(xyz - prior) > 0.18 or (xyz[2] < origin[2] - 0.001):
                raise ValueError('Clearance must be finite, bounded and not descend into tiles')
            points.append(xyz.tolist())
            prior = xyz
        replies = []
        for xyz in points:
            a = robo.state().arm(arm)
            angles = dict(pitch=a.pitch, yaw=a.yaw, roll=a.roll)
            preview = robo.preview_move(xyz, arm=arm, path='line', **angles)
            if not preview.get('reachable') or preview.get('ik_error') or preview.get('note'):
                return dict(self._state(robo), status='clearance_replan_required', preview=preview, completed_waypoints=len(replies))
            reply = robo.move_to(xyz, arm=arm, path='line', gripper=robo.KEEP, **angles)
            replies.append(str(reply))
            if not reply.reached or reply.blocked:
                return dict(self._state(robo), status='clearance_replan_required', reply=str(reply), completed_waypoints=len(replies) - 1)
        result = dict(self._state(robo), status='clearance_complete_reobserve', arm=arm, waypoints=points, replies=replies, actions_used=robo.action_count() - state['action_count'], scope='Caller observed empty arm, exact preview and replies; fresh RGB required before detector retry.')
        self.history.append(result)
        return result
